      for(const [id,key,total] of [['enquiry-main-census','registered',12],['enquiry-stress-census','outside',6]])q(id).innerHTML=c.map(x=>`<div class="census-row"><strong>${escape(Q.ROUTES.find(r=>r.id===x.route).title)}</strong><div class="census-bar" role="img" aria-label="${x[key].correct} correct, ${x[key].incorrect} incorrect, ${x[key].withheld} withheld of ${total}"><span class="correct-segment" style="width:${x[key].correct/total*100}%"></span><span class="incorrect-segment" style="width:${x[key].incorrect/total*100}%"></span><span class="hold-segment" style="width:${x[key].withheld/total*100}%"></span></div><small>${x[key].correct} correct · ${x[key].incorrect} incorrect · ${x[key].withheld} withheld<br>${x[key].queries} queries · ${x[key].ticks} decision ticks summed · ${x[key].missedWatches} missed watches</small></div>`).join('');
