      q('enquiry-actions').textContent=String(r?r.actions.length:6);q('enquiry-query-count').textContent=r?String(r.queries):'—';q('enquiry-deadline').textContent=(r?r.decisionTick:'—')+' / '+options.budget;
      q('enquiry-status').textContent=r?'Episode checked. Decisions are local simulations.':'Ready: receiving permission starts off.';
