      const reasons={'receiving-permission':'The represented models agree, but receiving permission is absent.','enquiry-removed':'The inherited route has finished, but the represented models still require different actions.','budget':'The deadline was reached before diagnosis or receiving checks completed.','query-permission':'Query permission is absent. No further response may be requested.','refresh-permission':'The required set is model-unanimous, but dependency refresh is not permitted.','watch':'A continuing watch was missed; receiving use is held.','stale':'The source version changed after qualification. The receipt cannot be used now.','source-version':'Responses from changed source versions cannot be merged.','coverage':'An audit already found a coverage contradiction in this fixture. Further receiving use is held.','empty-support':'No represented explanation fits the responses. Empty support does not warrant an answer.',unresolved:'More than one required action remains possible.',current:'Current receipt, fresh permission and continuing duties passed. Admission is still conditional on model coverage.'};
